import sys

def solve(n0, n1, n2):
    if n2 > 0:
        return "1" * (n2 + 1) + "0" * (n1 // 2) + "1" * (n1 % 2) + "0" * (n0 - n1 // 2)
    elif n1 > 0:
        return "1" * (n1 // 2 + 1) + "0" * (n1 % 2) + "1" * (n0 - n1 // 2)
    else:
        return "0" * (n0 + 1)

input = sys.stdin.read().split()
t = int(input[0])
results = []
index = 1
for _ in range(t):
    n0 = int(input[index])
    n1 = int(input[index + 1])
    n2 = int(input[index + 2])
    results.append(solve(n0, n1, n2))
    index += 3

print("\n".join(results))
